results.complete_sql:
SELECT source_type, MAX(size) AS max_size, MIN(size) AS min_size 
FROM space_debris 
GROUP BY source_type;

SELECT genre, songname, streams 
FROM music 
WHERE (genre, streams) IN (
    SELECT T1.genre, MAX(T1.streams) FROM music AS T1 JOIN music AS T2 ON T1.genre = T2.genre GROUP BY T1.genre
)
OR (genre, streams) IN (
    SELECT T1.genre, MIN(T1.streams) FROM music AS T1 JOIN music AS T2 ON T1.genre = T2.genre GROUP BY T1.genre
)
ORDER BY genre, streams;

SELECT country, year, SUM(rainfall) AS total_rainfall, RANK() OVER (ORDER BY SUM(rainfall) DESC) as rank 
FROM rainfalldata 
GROUP BY country, year;

SELECT country, AVG(avg_depth) AS avg_depth 
FROM marine_protected_areas 
GROUP BY country;

